// It uses unconstrained decoding outside << and >> to generate the rest of the text.
// The valid << >> content is preserved by maintaining a parser-valid prefix during constrained decoding.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideDelimiters: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideDelimiters ==> parser.IsValidPrefix(currentConstrained) && !parser.IsCompletePrefix(currentConstrained)
  decreases maxSteps - steps
{
  var next := if insideDelimiters
    then helpers.ConstrainedStep(lm, parser, prompt, currentConstrained, eosToken)
    else helpers.UnconstrainedStep(lm, prompt, generated);

  if next == eosToken { break; }

  generated := generated + [next];
  steps := steps + 1;

  if insideDelimiters {
    currentConstrained := currentConstrained + [next];
    if next == ">>" { insideDelimiters := false; }
  } else {
    if next == "<<" { insideDelimiters := true; currentConstrained := []; }
  }
}

